Method.Implementation:
	 #DIM status AS %Status
	 set status = $$$OK
	 #dim exceptionString As %String="JAVAEXCEPTION"
	 $$$TRACE("IHC.ITF.ITFCOMMON.CDR.XMLProxyTuxedoServiceOperation..Inside OnMessage method")
	 try{


		 		$$$TRACE(" Calling Tuxedo Service .."_pRequest.StringValue)

		 		set tsc = $$$OK
		 		set pResponse=##class(Ens.StringResponse).%New()
		 		Set pResponse.StringValue = ..objCdrTuxService.callAddUpdate(pRequest.StringValue)

		 		Set respData = pResponse.StringValue
		 		if (pResponse.StringValue[exceptionString){

			 	   SET ex = ##class(%Exception.General).%New("JavaException","JavaException",,
                             "pResponse.StringValue")
                   set pResponse.StringValue=""
       			   THROW ex
		 		}

		 		$$$TRACE(" Call after the Xmlproxy Call .."_respData)



	 }catch err{	

	     	 $$$TRACE("Exception in calling Add/Update: " _err.AsSystemError() _ " _ ErrData: " _ err.Data _ "; ErrCode:" _ err.Code)

		set errText=err.Data
	    set errText = $SYSTEM.Status.GetOneErrorText(status)
	    if ((errText["CONNECTIONERROR")){
		   Set status = ##class(IHC.ITF.ITFCOMMON.Utility).RetryMsgError(..%ConfigName,errText)
	    }Elseif errText["RESEND"{
		   Set status = ##class(IHC.ITF.ITFCOMMON.Utility).RetryMsgError(..%ConfigName,errText)
	    }Elseif errText["DATAERROR"{
		   Set status = ##class(IHC.ITF.ITFCOMMON.Utility).FailMsgError(..%ConfigName,errText)
	    }Elseif errText["SHUTDOWN"{
		   Set status = ##class(IHC.ITF.ITFCOMMON.Utility).RetryMsgError(..%ConfigName,errText)
	    }Else{
		    Set status = ##class(IHC.ITF.ITFCOMMON.Utility).RetryMsgError(..%ConfigName,errText)
	    }
	    if (errText'["DATAERROR"){
		    Try {
		    	do ..OnTearDown()
	    	}catch{}
	    	Set tSC = ..GetConnection(.tGateway, ..ConnectTimeout+10)
			If $$$ISERR(tSC) {
				set errText = $SYSTEM.Status.GetOneErrorText(tSC)
				Set status = ##class(IHC.ITF.ITFCOMMON.Utility).RetryMsgError(..%ConfigName,errText)
			}Else {
				// Open the connection
	    		set ..objCdrTuxService = ##class(org.ihc.itf.cdr.CdrStringAddUpdate).%New(..JavaGateway,..ApplicationAddress, ..TuxedoService)
			}
	    }  
	 }
	 return status

do ##super() $$$TRACE(" Inside OnInit() method...")
#DIM status AS %Status set status = $$$OK
$$$TRACE("OnInit..Inside method1 "_ ..JarFile) Do ..JavaGateway.%Import(..JarFile)
try{ $$$TRACE("OnInit..ApplicationAddress "_ ..ApplicationAddress) $$$TRACE("OnInit..TuxedoService "_ ..TuxedoService) set ..objCdrTuxService = ##class(org.ihc.itf.cdr.CdrStringAddUpdate).%New(..JavaGateway,..ApplicationAddress, ..TuxedoService)
}catch err{ $$$TRACE("Exception while Creating Tuxedo Service: " _err.AsSystemError() _ " _ data: " _ err.Data _ "; code:" _ err.Code) Set status = ##class(IHC.ITF.ITFCOMMON.Utility).DisableMsgError(..%ConfigName,"Service Exception while initializing Tuxedo Service. " _ err.AsSystemError() _ " _ data: " _ err.Data _ "; code:" _ err.Code) } Quit status


$$$TRACE(" $$$$$$$$$$$$$$$ Inside OnTearDown() method...")

Set tSC = $$$OK

Try {		
	If $IsObject(..objCdrTuxService) {
		$$$TRACE("Disconnecting from CDR Tuxedo service...")
		Do ..objCdrTuxService.shutdownTuxService()		
		Set ..objCdrTuxService = $$$NULLOREF
	}
}
Catch {
	Set tSC = $$$EnsSystemError
}
Set tSC = ##super()
Quit tSC
